function longestPalindrome(s: string): string {
  let start = 0
  let bestLen = 1
  function expand(l: number, r: number) {
    while (l >= 0 && r < s.length && s[l] === s[r]) {
      if (r - l + 1 > bestLen || (r - l + 1 === bestLen && l < start)) {
        bestLen = r - l + 1
        start = l
      }
      l--
      r++
    }
  }
  for (let i = 0; i < s.length; i++) {
    expand(i, i)
    expand(i, i + 1)
  }
  return s.slice(start, start + bestLen)
}
